library IEEE;
use IEEE.std_logic_1164.all;

entity full_adder is        -- a one-bit full adder
  port ( A, B, Cin: in BIT;   -- three binary inputs
         S, Cout: out BIT );  -- two binary outputs
end full_adder;

architecture full_adder_arch of full_adder is
begin
  S    <= A xor B xor Cin;
  Cout <= (B and Cin) or (A and Cin) or (A and B);
end full_adder_arch;

entity Inhibit is      -- also known as 'BUT-NOT'
  port ( X: in BIT;      -- as in 'X but not Y'
         Y: in BIT;
         Z: out BIT );   -- no semicolon after the last one
end Inhibit;

architecture Inhibit_arch of Inhibit is
begin
  Z <= '1' when X='1' and Y='0' else '0';
end Inhibit_arch;

