architecture prime9_arch of prime is
begin
  process(N)
    variable NI: INTEGER;
    variable prime: boolean;
  begin
    NI := CONV_INTEGER(N);
    prime := true;
    if NI=1 or NI=2 then null;      -- boundary cases
    else
      for i in 2 to 253 loop
        if NI mod i = 0 and NI /= i then
          prime := false; exit;
        end if;
      end loop;
    end if;
    if prime then F <= '1'; else F <= '0'; end if;
  end process;
end prime9_arch;

