entity V74x138 is
  port ( G1:    in STD_LOGIC;                     -- enable inputs
         G2A_L: in STD_LOGIC;
         G2B_L: in STD_LOGIC;
         A:     in STD_LOGIC_VECTOR (2 downto 0); -- select inputs
         Y_L:   out STD_LOGIC_VECTOR (0 to 7) );  -- decoded outputs
end V74x138;

architecture V74x138_a of V74x138 is
  signal Y_L_i: STD_LOGIC_VECTOR (0 to 7);
begin
  with A select Y_L_i <=
    "01111111" when "000",
    "10111111" when "001",
    "11011111" when "010",
    "11101111" when "011",
    "11110111" when "100",
    "11111011" when "101",
    "11111101" when "110",
    "11111110" when "111",
    "11111111" when others;
  Y_L <= Y_L_i when (G1 and not G2A_L and not G2B_L) = '1'
         else "11111111";
end V74x138_a;

entity parity9 is
  port ( I: in STD_LOGIC_VECTOR (1 to 9);
         EVEN, ODD: out STD_LOGIC );
end parity9;

architecture parity9p of parity9 is
begin
  process (I)
    variable p: STD_LOGIC;
  begin
    p := I(1);
    for j in 2 to 9 loop
      if I(j) = '1' then p := not p;
      end if;
    end loop;
    ODD  <= p;
    EVEN <= not p;
  end process;
end parity9p;
